package com.lingualearn.app.data.content

/**
 * English (en) and Portuguese (pt) comprehensive curriculum content.
 * 10 levels × 6 topics = 60 distinct lessons per language.
 */
object EnglishCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("Hello! / Good morning", "Friendly and standard greetings", "heh-LOH / good MOR-ning", "Good morning! How are you doing today?", "Standard polite greeting used worldwide.", "'Hi' is casual; 'Good morning/afternoon' is formal.")
                "Introducing Yourself" -> CurriculumLessonContent("My name is Alex", "Stating your name", "my naym ihz AL-eks", "Hello, my name is Alex and I am from Canada.", "Self-introduction formula.", "You can also say 'I am Alex' or 'I'm Alex'.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("Yes / No / Please / Thank you", "Essential polite responses", "yes / noh / pleez / thank yoo", "Yes, please! Thank you very much for your help.", "Core polite interactions.", "'You're welcome' or 'No problem' replies to thank you.")
                "Numbers 1–10" -> CurriculumLessonContent("One, two, three, four, five...", "1 to 10 cardinal numerals", "wuhn, too, three, for, fyv", "I would like two cups of coffee, please.", "Counting foundational items.", "English numbers 1-10 are irregular and essential.")
                "Basic Pronouns" -> CurriculumLessonContent("I, you, he, she, it, we, they", "Subject personal pronouns", "eye, yoo, hee, shee, iht, wee, thay", "We are learning English together every day.", "Foundational pronouns.", "'You' is used for both singular and plural.")
                else -> CurriculumLessonContent("Excuse me and Goodbye", "Polite courtesy and farewell", "ek-SKYOOS mee / good-BYE", "Excuse me, where is the nearest subway station?", "Everyday courtesy phrases.", "'See you later' is a natural casual farewell.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("Family (parents, brother, sister)", "Immediate family members", "FAM-uh-lee", "My older brother works as an architect in London.", "Describing relatives.", "English distinguishes siblings by age: older and younger.")
                "Colors" -> CurriculumLessonContent("Red, Blue, Yellow, Green, White", "Primary and secondary colors", "red, bloo, YEL-oh, green, wyt", "She wore a bright blue jacket to the interview.", "Color descriptors.", "In English, adjectives always precede the noun: 'blue jacket'.")
                "Food" -> CurriculumLessonContent("Breakfast, bread, and fresh fruit", "Everyday meals and produce", "BREK-fuhst, bred, froot", "For breakfast, I usually have oatmeal with fresh berries.", "Talking about food.", "Countable vs uncountable: 'bread' is uncountable, 'apple' is countable.")
                "Days & Months" -> CurriculumLessonContent("Monday through Sunday", "Seven days of the week", "MUHN-day throo SUHN-day", "We are planning a picnic in the park this Saturday.", "Calendar vocabulary.", "In English, days of the week and months are always capitalized.")
                "Simple Questions" -> CurriculumLessonContent("Who? What? Where? When? Why?", "Five basic interrogatives", "hoo, wuht, wayr, wen, wy", "Where is the boarding gate for flight 204?", "Asking questions.", "English uses 'do/does' auxiliary verbs to form questions.")
                else -> CurriculumLessonContent("Eat, drink, go, come", "Four essential action verbs", "eet, dringk, goh, kuhm", "Let's go to the cafeteria and drink some iced tea.", "Common everyday verbs.", "These verbs are irregular in the past tense (ate, drank, went, came).")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("Waking up early and commuting", "Everyday morning schedule", "WAY-king uhp / kuh-MYOO-ting", "I wake up at seven and commute by train to work.", "Describing routines.", "Use the simple present tense for habitual actions.")
                "Shopping" -> CurriculumLessonContent("How much does this cost?", "Inquiring about prices", "how muhch duhz this kawst", "Excuse me, how much does this leather jacket cost?", "Essential shopping phrase.", "Use 'How much is...' for singular and 'How much are...' for plural.")
                "Time" -> CurriculumLessonContent("What time is it right now?", "Asking the current hour", "wuht tym ihz iht", "It is half past two in the afternoon.", "Telling time accurately.", "'Half past' means :30; 'quarter to' means 15 minutes before.")
                "Directions" -> CurriculumLessonContent("Go straight and turn right", "Navigating city streets", "goh strayt / turn ryt", "Go straight for two blocks and turn right at the traffic lights.", "Giving directions.", "Imperative verbs (go, turn, cross) are used for directions.")
                "Simple Sentences" -> CurriculumLessonContent("I would like to book a flight", "Expressing polite desires", "eye wood lyk", "I would like to reserve a window seat on the morning flight.", "Polite sentence structure.", "'I would like' is considerably more polite than 'I want'.")
                else -> CurriculumLessonContent("How have you been lately?", "Casual conversational check-in", "how hav yoo been", "I've been doing great, thanks for asking! How about you?", "Natural conversation starter.", "'Not bad' or 'Can't complain' are common friendly replies.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("Yesterday I visited the national museum", "Recounting completed actions", "YES-ter-day eye VIZ-uh-tid", "Yesterday we explored the historical exhibits downtown.", "Simple past narrative.", "Regular past verbs add -ed; many common verbs are irregular.")
                "Future Plans" -> CurriculumLessonContent("I am going to travel next month", "Near future intentions", "eye am GOH-ing too TRAV-uhl", "Next summer, I am going to study literature abroad.", "Future with 'going to'.", "Use 'going to' for planned decisions and 'will' for spontaneous ones.")
                "Travel" -> CurriculumLessonContent("Boarding pass and departure gate", "Airport transit terminology", "BOR-ding pas / dee-PAR-cher", "Please have your boarding pass and passport ready at the gate.", "Navigating international travel.", "Check-in, baggage drop, and customs are key airport steps.")
                "Restaurants" -> CurriculumLessonContent("Could we have the check, please?", "Requesting the restaurant bill", "kood wee hav theh chek", "Everything was delicious, could we have the check please?", "Polite dining request.", "'Check' is standard in American English; 'bill' in British English.")
                "Describing People" -> CurriculumLessonContent("Outgoing, empathetic, and reliable", "Describing personality traits", "OWT-goh-ing / em-puh-THET-ik", "Our project manager is empathetic, organized, and reliable.", "Character adjectives.", "Combine adjectives with commas and 'and' for balanced descriptions.")
                else -> CurriculumLessonContent("The weather is wonderful today, isn't it?", "Discussing seasonal weather", "THEH WETH-er ihz", "It's so sunny and mild today; perfect for an afternoon stroll.", "Everyday small-talk opener.", "Weather discussions are classic social icebreakers in English culture.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("Could I chime in on that point?", "Politely joining a discussion", "kood eye chym in", "Could I chime in and offer an alternative perspective?", "Conversational participation.", "'Chime in' is a natural phrasal idiom meaning to contribute briefly.")
                "Opinions" -> CurriculumLessonContent("From my perspective", "Stating reasoned viewpoints", "fruhm my per-SPEK-tiv", "From my perspective, sustainable innovation drives long-term success.", "Articulating viewpoints.", "Using phrases like 'In my view' softens dogmatic assertions.")
                "Experiences" -> CurriculumLessonContent("A truly memorable journey", "Recounting milestone life events", "MEM-ruhr-buhl JUR-nee", "Hiking across the national park was a truly memorable experience.", "Sharing life reflections.", "The present perfect links past experience to present context.")
                "Comparisons" -> CurriculumLessonContent("Far more advantageous than", "Comparative analysis", "far mor ad-van-TAY-juhs", "Remote collaboration proved far more advantageous than we anticipated.", "Making nuanced comparisons.", "Use 'far more' or 'much less' to intensify comparative degrees.")
                "More Complex Grammar" -> CurriculumLessonContent("Conditional clauses with 'If'", "Hypothetical situations", "kuhn-DISH-nuhl klaw-ziz", "If we had known the schedule earlier, we would have attended.", "Third conditional structure.", "Third conditionals express counterfactual past regret.")
                else -> CurriculumLessonContent("English podcast listening comprehension", "Auditory practice with podcasts", "POHD-kast LIS-ning", "Listening to interviews helps decipher natural spoken contractions.", "Sharpening listening skills.", "Pay attention to connected speech, reduced vowels, and word stress.")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("Once upon a time in a bustling city", "Narrative storytelling formula", "wuhns uh-PAWN uh tym", "Suddenly, an unexpected opportunity changed the protagonist's life.", "Narrative prose techniques.", "Storytelling alternates between past continuous and simple past.")
                "Workplace Conversations" -> CurriculumLessonContent("Action items and milestone review", "Corporate project management", "AK-shuhn EYE-tuhmz", "Let's review the quarterly deliverables and assign action items.", "Professional workplace language.", "'Action item' refers to a specific task assigned to a team member.")
                "Social Situations" -> CurriculumLessonContent("Thank you so much for hosting us", "Gracious social etiquette", "HOHS-ting uhs", "Thank you for the wonderful dinner; your hospitality was amazing.", "Social courtesy and dining etiquette.", "Sending a thank-you note or message after an event is standard.")
                "News & Media" -> CurriculumLessonContent("Headline news and editorial analysis", "Journalistic commentary", "HED-lyn nooz", "The editorial outlines the economic impact of clean energy transitions.", "Media and journalism vocabulary.", "Passive constructions are prevalent in journalistic reporting.")
                "Idiomatic Expressions" -> CurriculumLessonContent("Bite the bullet / Break the ice", "Common metaphorical idioms", "byt theh BOOL-iht", "Let's break the ice before starting the workshop with a quick game.", "Natural idiomatic fluency.", "'Break the ice' means to relieve tension and get people talking.")
                else -> CurriculumLessonContent("Phrasal verbs in everyday speech", "Multi-word verb combinations", "FRAY-zuhl verbs", "We decided to call off the meeting and catch up next week.", "Mastering phrasal verbs.", "Phrasal verbs like 'call off' (cancel) and 'catch up' define fluent English.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("Addressing global socio-economic shifts", "High-register societal debate", "soh-see-oh-ek-uh-NAHM-ik", "We must examine the long-term societal ramifications of automation.", "Discussing complex topics.", "Abstract nouns ending in -tion, -ity, and -ment enrich analytical speech.")
                "Debate & Opinions" -> CurriculumLessonContent("I respectfully beg to differ", "Polite and firm disagreement", "beg too DIF-er", "While I understand your rationale, I respectfully beg to differ.", "Cultured debate etiquette.", "'Beg to differ' expresses disagreement without hostility.")
                "Abstract Topics" -> CurriculumLessonContent("Ethics, consciousness, and artificial intelligence", "Philosophical inquiries", "ETH-iks / KAHN-shuhs-nis", "Debating the philosophical boundaries between cognition and consciousness.", "Conceptual and ethical discourse.", "Philosophy demands precise distinctions between terms.")
                "Natural Expressions" -> CurriculumLessonContent("Touch and go / Hit the nail on the head", "Everyday idiomatic cadences", "tuhtch and goh", "Her concise summary really hit the nail right on the head.", "Idiomatic precision.", "'Hit the nail on the head' means to describe a situation exactly.")
                "Listening Comprehension" -> CurriculumLessonContent("Keynote symposium lectures", "Comprehending rapid academic speeches", "KEE-noht sim-POH-zee-uhm", "Taking comprehensive notes while following fast technical lectures.", "Academic auditory mastery.", "Focus on transitional discourse markers like 'nonetheless' and 'conversely'.")
                else -> CurriculumLessonContent("Writing argumentative essays", "Structured written composition", "ar-gyoo-MEN-tuh-tiv", "A compelling thesis supported by rigorous empirical evidence.", "Scholarly writing standards.", "A strong essay features a clear thesis, counterarguments, and conclusion.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("Strategic deliberations and contingency plans", "Executive decision-making", "kuhn-TIN-juhn-see", "We must formulate contingency plans to mitigate geopolitical risks.", "Executive management vocabulary.", "'Contingency plan' refers to a backup strategy for unforeseen events.")
                "Cultural Context" -> CurriculumLessonContent("Shakespeare and the legacy of English literature", "Literary and cultural heritage", "SHAYK-speer", "Shakespeare's sonnets and plays fundamentally shaped the English lexicon.", "Cultural depth and literary history.", "Many everyday English idioms trace their origin to Shakespeare.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("Ephemeral, pragmatic, and ubiquitous", "Sophisticated literary adjectives", "eh-FEM-ruhl / prag-MAT-ik", "Smartphones have become ubiquitous in modern metropolitan life.", "High-register vocabulary.", "Deploy elevated adjectives to introduce subtlety into arguments.")
                "Advanced Listening" -> CurriculumLessonContent("Deciphering regional English accents", "Global English phonetic variety", "AKS-ents", "Navigating British, Scottish, Australian, and regional American dialects.", "Global English auditory skill.", "English is spoken with diverse rhotic and non-rhotic regional cadences.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("Register modulation across professional contexts", "Shifting tone and register", "REJ-is-ter mod-yoo-LAY-shuhn", "Transitioning seamlessly from casual banter to boardroom presentations.", "Mastering social registers.", "Understand the difference between Latinate formal words and Germanic casual ones.")
                else -> CurriculumLessonContent("Inversion and subjunctive structures", "Advanced stylistic grammar", "in-VER-zhuhn", "Rarely have we witnessed such remarkable resilience under pressure.", "Stylistic grammatical flair.", "Inversion puts negative adverbs first for emphatic rhetorical weight.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("Cross-border bilateral negotiations", "High diplomacy and commerce", "by-LAT-er-uhl neh-goh-shee-AY-shuhnz", "The signatories ratified a landmark bilateral investment treaty.", "Diplomatic and legal precision.", "Agreements require unambiguous legal vocabulary.")
                "Advanced Reading" -> CurriculumLessonContent("George Orwell and Virginia Woolf", "Modernist literature and critical reading", "OR-wel / woolf", "Analyzing allegorical subtext in 1984 and modernist stream of consciousness.", "Literary criticism and depth.", "Appreciating irony, allegory, and narrative voice.")
                "Idioms & Expressions" -> CurriculumLessonContent("Burn the midnight oil / Double-edged sword", "Cultivated metaphorical idioms", "burnd theh MID-nyt oyl", "Developing disruptive technology is often a double-edged sword.", "Expressive metaphor mastery.", "'Double-edged sword' signifies something with both benefits and hazards.")
                "Advanced Writing" -> CurriculumLessonContent("Peer-reviewed monographs and white papers", "Scholarly publications", "peer ree-VYOOD", "Publishing peer-reviewed research with rigorous statistical integrity.", "Scholarly composition.", "Academic publications demand precise terminology and passive objectivity.")
                "Difficult Listening" -> CurriculumLessonContent("Live parliamentary hearings and cross-examinations", "High-speed interrogative speech", "par-luh-MEN-tuh-ree", "Comprehending rapid exchanges, interruptions, and barbed rhetorical queries.", "Supreme auditory comprehension.", "Following rapid banter and legal cross-examinations live.")
                else -> CurriculumLessonContent("Near-native eloquence and spontaneous wit", "Total linguistic poise", "EL-uh-kwuhns", "Articulating multi-faceted arguments with natural poise and witty repartee.", "Bilingual mastery.", "Effortless confidence across any subject matter.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("Flawless communicative poise", "Unrestricted conversational ease", "poyz", "The dialogue flowed with effortless grace, humor, and natural rhythm.", "Native-level ease.", "Zero hesitation, native cadence, and intuitive phrasing.")
                "Humor & Cultural References" -> CurriculumLessonContent("Subtle irony, satire, and dry understatement", "Appreciating Anglo-Saxon humor", "EYE-ruh-nee / SAT-yr", "Appreciating British dry understatement and satirical wordplay instantly.", "Cultural humor mastery.", "Understatement is the cornerstone of British and Anglophone humor.")
                "Advanced Debates" -> CurriculumLessonContent("Masterful rhetoric and charismatic oratory", "Commanding public speech", "RET-er-ik / OR-uh-tree", "Delivering a keynote address that captivated the entire global auditorium.", "Public oration at the highest level.", "Mastery over rhetorical cadence, pauses, and persuasive ethos.")
                "Professional Fluency" -> CurriculumLessonContent("Global multinational executive leadership", "Leading international enterprises", "eg-ZEK-yoo-tiv", "Chairing the World Economic Forum plenary session with absolute command.", "Executive global fluency.", "Directing international negotiations with authority and charm.")
                "Native-Speed Listening" -> CurriculumLessonContent("Instantaneous auditory cognitive processing", "Flawless real-time listening", "aw-duh-TOR-ee", "Catching every mumbled aside and rapid cultural quip in real time.", "Supreme acoustic discernment.", "Not a single beat or subtle reference is missed.")
                else -> CurriculumLessonContent("Complete bicultural and linguistic mastery", "Living and thinking seamlessly in English", "by-KUL-cher-uhl", "Effortlessly navigating the literature, culture, and ethos of the English-speaking world.", "Total linguistic and cultural harmony.", "True bilingual and bicultural achievement.")
            }
        }
    }
}

object PortugueseCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("Olá! / Bom dia / Boa tarde", "Hello! / Good morning / Good afternoon", "oh-LAH / bohn JEE-ah / BOH-ah TAR-jee", "Olá! Tudo bem com você hoje?", "Hello! Is everything good with you today?", "'Tudo bem?' is the quintessential Brazilian check-in.")
                "Introducing Yourself" -> CurriculumLessonContent("Meu nome é Lucas, muito prazer", "My name is Lucas, nice to meet you", "mew NOH-mee eh LOO-kas", "Meu nome é Lucas e eu sou do Brasil.", "My name is Lucas and I am from Brazil.", "'Muito prazer' expresses genuine delight upon meeting.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("Sim / Não / Por favor / Obrigado", "Yes / No / Please / Thank you", "seen / nown / poor fah-VOHR / oh-bree-GAH-doo", "Sim, por favor! Muito obrigado pela ajuda.", "Yes, please! Thank you very much for the help.", "Men say 'obrigado'; women say 'obrigada'.")
                "Numbers 1–10" -> CurriculumLessonContent("Um, dois, três, quatro, cinco...", "1 to 10 numerals", "oon, doys, trays, KWAH-troo, SEEN-koo", "Dois sucos de maracujá, por favor.", "Two passionfruit juices, please.", "In Brazilian Portuguese, 'dois' (m) and 'duas' (f) agree with the noun.")
                "Basic Pronouns" -> CurriculumLessonContent("Eu, você, ele, ela, nós, eles", "I, you, he, she, we, they", "EH-oo, voh-SAY, EH-lee, EH-lah, nohs", "Nós estamos aprendendo português juntos.", "We are learning Portuguese together.", "'Você' is universally used in Brazil for friendly 'you'.")
                else -> CurriculumLessonContent("Com licença e Até logo", "Excuse me and See you later", "kohn lee-SEN-sah / ah-TEH LOH-goo", "Com licença, onde fica a praia de Copacabana?", "Excuse me, where is Copacabana beach?", "'Tchau' (from Italian ciao) is the ubiquitous casual goodbye.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("A família (pais, irmão, irmã)", "Family (parents, brother, sister)", "ah fah-MEE-lyah", "Meu irmão mora em São Paulo e minha irmã no Rio.", "My brother lives in São Paulo and my sister in Rio.", "Possessive adjectives agree: 'meu irmão', 'minha irmã'.")
                "Colors" -> CurriculumLessonContent("Vermelho, azul, amarelo, verde, branco", "Red, Blue, Yellow, Green, White", "vehr-MEH-lyoo, ah-ZOOL, ah-mah-REH-loo", "A bandeira brasileira é verde e amarela.", "The Brazilian flag is green and yellow.", "Adjectives follow nouns and agree in gender and number.")
                "Food" -> CurriculumLessonContent("Feijoada, pão de queijo e açaí", "Feijoada, cheese bread, and açaí", "fay-zhoo-AH-dah, pown jee KAY-zhoo", "A feijoada completa aos sábados é uma delícia.", "Full feijoada on Saturdays is delicious.", "Pão de queijo from Minas Gerais is a beloved breakfast staple.")
                "Days & Months" -> CurriculumLessonContent("Segunda-feira a Domingo", "Monday to Sunday", "seh-GOON-dah FAY-rah", "No sábado vamos dar uma volta na praia.", "On Saturday we will take a stroll on the beach.", "Weekdays in Portuguese are numbered: segunda-feira, terça-feira, etc.")
                "Simple Questions" -> CurriculumLessonContent("Quem? O que? Onde? Quando? Por quê?", "Who? What? Where? When? Why?", "kayn, oo kay, OHN-jee, KWAHN-doo, poor KAY", "Onde fica o ponto de ônibus mais próximo?", "Where is the nearest bus stop located?", "Notice: 'Por que' (question) versus 'porque' (because).")
                else -> CurriculumLessonContent("Comer, beber, ir, vir", "Eat, drink, go, come", "koh-MEHR, beh-BEHR, eer, veer", "Nós vamos almoçar juntos no restaurante por quilo.", "We are going to have lunch together at the buffet restaurant.", "Buffet restaurants by weight ('por quilo') are popular across Brazil.")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("Acordar cedo e tomar café da manhã", "Waking up early and having breakfast", "ah-kohr-DAHR SEH-doo", "Eu acordo às sete da manhã e tomo um café bem forte.", "I wake up at seven in the morning and drink strong coffee.", "Breakfast in Portuguese is literally 'morning coffee' (café da manhã).")
                "Shopping" -> CurriculumLessonContent("Quanto custa isso?", "How much does this cost?", "KWAHN-too KOOS-tah EE-soo", "Moço, quanto custa essa camiseta de algodão?", "Sir, how much is this cotton t-shirt?", "'Moço' / 'moça' are polite friendly ways to address shopkeepers.")
                "Time" -> CurriculumLessonContent("Que horas são?", "What time is it?", "kay OH-rahs sown", "São duas e meia da tarde.", "It is 2:30 in the afternoon.", "Use 'É uma hora' for 1:00, and 'São...' for all other hours.")
                "Directions" -> CurriculumLessonContent("Siga em frente e vire à direita", "Go straight and turn right", "SEE-gah aym FREN-chee", "Siga em frente por dois quarteirões e vire à esquerda.", "Go straight for two blocks and turn left.", "'Direita' is right, 'esquerda' is left.")
                "Simple Sentences" -> CurriculumLessonContent("Eu gostaria de pedir um suco", "I would like to order a juice", "gos-tah-REE-ah", "Eu gostaria de uma mesa ao ar livre, por favor.", "I would like an outdoor table, please.", "'Gostaria' is the polite conditional of 'gostar'.")
                else -> CurriculumLessonContent("E aí, tudo joia?", "Hey, is everything great? (colloquial)", "ee eye, TOO-doo ZHOY-ah", "Tudo joia! Como foi o seu fim de semana?", "Everything's great! How was your weekend?", "'Tudo joia' and 'tudo beleza' are popular casual greetings.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("Ontem eu visitei o Corcovado", "Yesterday I visited Corcovado", "OHN-tayn eh-oo vee-zee-TAY", "Ontem nós subimos até o Cristo Redentor no Rio.", "Yesterday we climbed up to Christ the Redeemer in Rio.", "Pretérito perfeito describes completed past events.")
                "Future Plans" -> CurriculumLessonContent("Vou viajar para Salvador no próximo mês", "I am going to travel to Salvador next month", "voh vyah-ZHAR", "Nas próximas férias, vou conhecer as praias da Bahia.", "During next vacation, I will explore the beaches of Bahia.", "'Ir + infinitive' forms the near future in everyday Portuguese.")
                "Travel" -> CurriculumLessonContent("A passagem aérea e o embarque", "Airline ticket and boarding", "pah-SAH-zhayn ah-EH-ree-ah", "O voo para Florianópolis já está no portão de embarque.", "The flight to Florianópolis is already at the boarding gate.", "Brazilians travel vast domestic distances by plane or executive bus.")
                "Restaurants" -> CurriculumLessonContent("A conta, por favor", "The bill, please", "ah KOHN-tah", "O churrasco estava excelente, a conta por favor.", "The barbecue was excellent, the bill please.", "A 'churrascaria' offers an endless rotation of grilled meats.")
                "Describing People" -> CurriculumLessonContent("Alegre, simpático e acolhedor", "Cheerful, friendly, and welcoming", "ah-LEH-gree, seen-PAH-tee-koo", "O povo brasileiro é conhecido por ser caloroso e simpático.", "The Brazilian people are renowned for being warm and friendly.", "Brazilians are famous for their open hospitality ('acolhimento').")
                else -> CurriculumLessonContent("Que dia lindo de sol!", "What a beautiful sunny day!", "kay JEE-ah LEEN-doo", "O tempo no litoral está perfeito para um mergulho.", "The weather on the coast is perfect for a swim.", "Sunny weather naturally invites outdoor beach life.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("Posso dar uma sugestão?", "May I make a suggestion?", "POS-soo dar", "Gostaria de acrescentar uma observação importante a esse debate.", "I'd like to add an important observation to this discussion.", "Polite participative conversational formulas.")
                "Opinions" -> CurriculumLessonContent("Na minha opinião", "In my opinion", "nah MEEN-yah oh-pee-nee-OWN", "Na minha opinião, a diversidade cultural enriquece o país.", "In my opinion, cultural diversity enriches the country.", "'Na minha opinião' introduces viewpoints constructively.")
                "Experiences" -> CurriculumLessonContent("Uma experiência inesquecível", "An unforgettable experience", "ee-nes-keh-SEE-vel", "Navegar pela floresta amazônica foi uma experiência única.", "Navigating through the Amazon rainforest was a unique experience.", "Recounting milestone travel and nature memories.")
                "Comparisons" -> CurriculumLessonContent("Mais interessante do que", "More interesting than", "myz een-teh-reh-SAHN-chee", "Esse documentário é muito mais informativo do que o artigo.", "This documentary is much more informative than the article.", "Use 'mais... do que' for comparative degrees.")
                "More Complex Grammar" -> CurriculumLessonContent("O pretérito imperfeito do subjuntivo", "Past subjunctive", "soob-zhoon-TEE-voo", "Se eu tivesse mais tempo livre, aprenderia a tocar violão.", "If I had more free time, I would learn to play acoustic guitar.", "'Se eu tivesse... eu tocaria' pairs subjunctive and conditional.")
                else -> CurriculumLessonContent("Compreensão auditiva com podcasts", "Listening comprehension with podcasts", "kohm-pree-en-SOWN", "Escutar rádios e notícias brasileiras para treinar o ouvido.", "Listening to Brazilian radio and news to train the ear.", "Notice the melodic musical rhythm of Brazilian Portuguese.")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("Era uma vez em uma cidadezinha", "Once upon a time in a small town", "EH-rah OO-mah vez", "De repente, uma lenda folclórica ganhou vida na floresta.", "Suddenly, a folkloric legend came to life in the forest.", "Rich Brazilian folklore features characters like Saci-Pererê and Curupira.")
                "Workplace Conversations" -> CurriculumLessonContent("A reunião de equipe e as metas", "Team meeting and quarterly targets", "reh-oo-nee-OWN", "Vamos alinhar os prazos e as entregas do projeto hoje.", "Let's align the deadlines and project deliverables today.", "Corporate Portuguese in São Paulo is dynamic and focused.")
                "Social Situations" -> CurriculumLessonContent("Obrigado pelo convite carinhoso", "Thank you for the warm invitation", "kohn-VEE-chee", "Ficamos muito felizes em compartilhar esse momento com vocês.", "We were very happy to share this moment with you all.", "'Abraço' (warm hug) is the standard cordial sign-off.")
                "News & Media" -> CurriculumLessonContent("As manchetes dos jornais", "Newspaper headlines", "mahn-SHEH-chees", "A imprensa destaca as inovações em energias renováveis.", "The press highlights innovations in renewable energy.", "Journalistic Portuguese uses polished and formal vocabulary.")
                "Idiomatic Expressions" -> CurriculumLessonContent("Tirar o cavalinho da chuva", "Give up false hopes (take little horse out of rain)", "tee-RAHR kah-vah-LEEN-yoo", "Se você acha que vai ser fácil, pode tirar o cavalinho da chuva.", "If you think it will be easy, you can abandon that illusion.", "Charming traditional Brazilian idiom.")
                else -> CurriculumLessonContent("O futuro do subjuntivo", "The future subjunctive", "FOO-too-roo do soob-zhoon-TEE-voo", "Quando você chegar ao Brasil, nós iremos à praia juntos.", "When you arrive in Brazil, we will go to the beach together.", "Portuguese is unique among Romance languages in using future subjunctive.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("Sustentabilidade e desenvolvimento social", "Sustainability and social development", "soos-ten-tah-bee-lee-DAH-jee", "O equilíbrio essencial entre preservação ambiental e economia.", "The vital balance between environmental conservation and economics.", "Debating complex socio-environmental themes.")
                "Debate & Opinions" -> CurriculumLessonContent("Discordo com todo o respeito", "I respectfully disagree", "jees-KOR-doo", "Entendo seus argumentos, contudo vejo a questão por outro prisma.", "I understand your arguments; however, I view the issue through another prism.", "Cultured debate with diplomatic politeness.")
                "Abstract Topics" -> CurriculumLessonContent("A 'saudade' e a identidade cultural", "The concept of 'Saudade' and cultural identity", "sow-DAH-jee", "A saudade expressa uma melancolia afetuosa e poética.", "Saudade expresses an affectionate and poetic melancholy.", "A uniquely Portuguese word describing deep nostalgic longing.")
                "Natural Expressions" -> CurriculumLessonContent("Dar um jeito / Fazer uma vaquinha", "Find a workaround / Pool money together", "dar oon ZHAY-too", "O brasileiro sempre encontra uma forma criativa de dar um jeito.", "Brazilians always find a creative way to make things work ('dar um jeito').", "Cultural expressions reflecting resourceful resilience.")
                "Listening Comprehension" -> CurriculumLessonContent("Acompanhar palestras universitárias", "Following university lectures", "pah-LEHS-trahs", "Compreender debates acadêmicos com ritmo rápido de fala.", "Comprehending fast-paced academic debates with ease.", "Listening for connected speech and rapid regional reductions.")
                else -> CurriculumLessonContent("Redação dissertativa e argumentativa", "Argumentative essay writing", "reh-dah-SOWN", "Estruturar uma tese consistente com introdução, desenvolvimento e conclusão.", "Structuring a coherent thesis with intro, body, and conclusion.", "Standard Brazilian ENEM university entrance essay model.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("Planejamento estratégico de longo prazo", "Long-term strategic planning", "strah-TEH-zhee-koo", "É fundamental ponderar todas as variáveis macroeconômicas.", "It is imperative to weigh all macroeconomic variables.", "Executive management and corporate vocabulary.")
                "Cultural Context" -> CurriculumLessonContent("Bossa Nova, Samba e MPB", "Bossa Nova, Samba, and Brazilian Popular Music", "BOH-sah NOH-vah", "Tom Jobim e Vinicius de Moraes revolucionaram a música mundial.", "Tom Jobim and Vinicius de Moraes revolutionized world music.", "Bossa Nova lyrics offer poetic masterclasses in Portuguese.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("Efêmero, sublime e acolhedor", "Ephemeral, sublime, and welcoming", "eh-FEH-meh-roo / soo-BLEE-mee", "A luz do entardecer sobre a Baía de Guanabara foi sublime.", "The sunset light over Guanabara Bay was sublime.", "Rich poetic and stylistic adjectives.")
                "Advanced Listening" -> CurriculumLessonContent("Sotaques regionais do Brasil", "Regional Brazilian accents", "soh-TAH-kees", "Diferenciar a cadência mineira, nordestina, gaúcha e carioca.", "Distinguishing Mineiro, Northeastern, Gaúcho, and Carioca cadences.", "Brazil's continental expanse creates rich regional musicality.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("Linguagem culta versus linguagem coloquial", "Cultured formal vs Colloquial register", "LEEN-gwah-zhayn KOOL-tah", "Adequar o registro linguístico com elegância e precisão.", "Adapting linguistic registers with elegance and precision.", "Mastering pronoun placement (próclise, ênclise) in formal prose.")
                else -> CurriculumLessonContent("O infinitivo pessoal flexionado", "The inflected personal infinitive", "een-fee-nee-TEE-voo", "É importante nós estudarmos para compreendermos as nuances.", "It is important for us to study in order to understand the nuances.", "Portuguese uniquely conjugates personal infinitives.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("Negociações diplomáticas e comerciais", "Diplomatic and commercial negotiations", "neh-goh-see-ah-SOYNS", "As delegações firmaram um tratado bilateral de cooperação técnica.", "The delegations signed a bilateral technical cooperation treaty.", "High corporate and diplomatic prose.")
                "Advanced Reading" -> CurriculumLessonContent("Machado de Assis e Clarice Lispector", "Machado de Assis and Clarice Lispector", "mah-SHAH-doo jee ah-SEES", "A ironia fina de Machado de Assis e o fluxo de consciência de Clarice.", "Machado de Assis's fine irony and Clarice Lispector's stream of consciousness.", "Appreciating universally acclaimed Brazilian literature.")
                "Idioms & Expressions" -> CurriculumLessonContent("Pisar em ovos / Ficar a ver navios", "Walk on eggshells / Left empty-handed", "pee-ZAHR aym OH-voos", "Depois de tantas promessas sem cumprimento, ficaram a ver navios.", "After so many broken promises, they were left completely empty-handed.", "Historical Portuguese idioms with maritime roots.")
                "Advanced Writing" -> CurriculumLessonContent("Monografia acadêmica e artigo de opinião", "Academic monograph and op-ed article", "moh-noh-grah-FEE-ah", "Produzir uma dissertação rigorosa com sólida fundamentação teórica.", "Producing a rigorous dissertation with solid theoretical groundwork.", "Scholarly composition.")
                "Difficult Listening" -> CurriculumLessonContent("Debates parlamentares no Congresso Nacional", "Parliamentary debates in Congress", "kohn-GREH-soo", "Captar ironias sutis e interpelações calorosas em tempo real.", "Capturing subtle ironies and heated interpellations in real time.", "Instant auditory comprehension of rapid political rhetoric.")
                else -> CurriculumLessonContent("Fluência com elegância nativa", "Fluency with native elegance", "floo-EN-see-ah", "Expressar ideias complexas com естеtismo, leveza e precisão.", "Expressing complex ideas with aesthetic grace, ease, and precision.", "Effortless bilingual fluency.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("Desenvoltura espontânea e fluidez", "Spontaneous poise and verbal fluidity", "deh-zen-vohl-TOO-rah", "A conversa flui com naturalidade absoluta e brilho comunicativo.", "The conversation flows with absolute naturalness and communicative radiance.", "Effortless native cadence.")
                "Humor & Cultural References" -> CurriculumLessonContent("Humor sutil, trocadilhos e malandragem", "Subtle humor, puns, and cultural wit", "troh-kah-JEE-lyoos", "Apreciar o humor refinado e a irreverência criativa brasileira.", "Appreciating refined humor and creative Brazilian irreverence.", "Culturally grounded humor.")
                "Advanced Debates" -> CurriculumLessonContent("Eloquência oratória e liderança", "Oratorical eloquence and leadership", "eh-loh-KWEN-see-ah", "Conduzir debates com persuasão lógica e carisma envolvente.", "Leading debates with logical persuasion and engaging charisma.", "Mastery over public oration.")
                "Professional Fluency" -> CurriculumLessonContent("Liderança executiva internacional", "International executive leadership", "lee-deh-RAHN-sah", "Presidir conselhos e negociações multinacionais em língua portuguesa.", "Chairing multinational boards and negotiations in Portuguese with distinction.", "Supreme executive leadership.")
                "Native-Speed Listening" -> CurriculumLessonContent("Percepção auditiva instantânea", "Instantaneous auditory perception", "pehr-sep-SOWN", "Captar cada inflexão e sutil nuance comunicativa sem esforço.", "Catching every inflection and subtle communicative nuance effortlessly.", "Total acoustic mastery.")
                else -> CurriculumLessonContent("Imersão total na cultura lusófona", "Total immersion in the Lusophone world", "ee-mehr-SOWN", "Viver, pensar e sentir com a plenitude da língua portuguesa.", "Living, thinking, and feeling with the fullness of the Portuguese language.", "Total cultural and linguistic harmony.")
            }
        }
    }
}
